const body = $input.first().json.body || {};
const operation = body.operation || $input.first().json.operation;

let outputIndex = 0;
switch (operation) {
  case 'login':
    outputIndex = 0;
    break;
  case 'create_user':
    outputIndex = 1;
    break;
  case 'update_avatar':
    outputIndex = 2;
    break;
  case 'update_password':
    outputIndex = 3;
    break;
  case 'list_users':
    outputIndex = 4;
    break;
  default:
    outputIndex = 0;
}

const result = [[], [], [], [], []];
result[outputIndex] = [{ json: JSON.parse(JSON.stringify($input.first().json)) }];
return result;

const dbUser = $input.first().json;
const inputPassword = $('Auth Webhook').first().json.body.password || $('Auth Webhook').first().json.body.body?.password;

if (!dbUser || !dbUser.email) {
  return [{ json: { success: false, message: 'User account not found.' } }];
}

if (dbUser.password_hash !== inputPassword) {
  return [{ json: { success: false, message: 'Invalid email or password.' } }];
}

return [{
  json: {
    success: true,
    user: {
      id: dbUser.id,
      email: dbUser.email,
      role: dbUser.role,
      avatar: dbUser.avatar,
      needs_password_change: !!dbUser.needs_password_change
    }
  }
}];
